const q = (($fromAI('query', 'The search query - be specific', 'string') || '')).trim();
if (!q) return 'Search failed: no query provided';
const res = await fetch('https://api.duckduckgo.com/?q=' + encodeURIComponent(q) + '&format=json&no_html=1&skip_disambiguation=1', { headers: { 'User-Agent': 'HomeBot' } });
if (!res.ok) return `Search failed (${res.status})`;
const d = await res.json();
const parts = [];
if (d.AbstractText) parts.push(d.AbstractText);
if (d.Answer) parts.push(String(d.Answer));
for (const t of (d.RelatedTopics || []).slice(0, 5)) {
  if (t.Text) parts.push(t.Text);
}
return parts.length ? parts.join('\n').slice(0, 4000) : `No results for "${q}"`;

// Auth Guard — deployed by HomeBot; validates X-HOMEBOT-Auth.
let secret = "";
if (!secret) secret = process.env.HOMEBOT_WEBHOOK_SECRET;
const hdrs = $input.first()?.json?.headers || {};
const incoming = hdrs['x-homebot-auth'] || hdrs['X-HOMEBOT-Auth'] || '';
if (!secret) {
  throw new Error('Unauthorized: this workflow has no HomeBot secret. Deploy it from HomeBot instead of importing it by hand.');
}
if (incoming !== secret) {
  throw new Error('Unauthorized: invalid or missing X-HOMEBOT-Auth header');
}
return $input.all();

const filePath = $fromAI('path', 'Full path to the file to read', 'string');
const fs = require('fs');
const os = require('os');
const path = require('path');
const HOME = os.homedir();
const resolved = path.resolve(filePath.replace(/^~/, HOME));
const homeWithSep = HOME.toLowerCase() + path.sep;
if (resolved.toLowerCase() !== HOME.toLowerCase() && !resolved.toLowerCase().startsWith(homeWithSep)) {
  return 'Error: access denied - path must be within the home directory';
}
try {
  const content = fs.readFileSync(resolved, 'utf8');
  return content.slice(0, 8000);
} catch (err) {
  return `Error reading file: ${err.message}`;
}

const filePath = $fromAI('path', 'Full path to write the file to', 'string');
const content = $fromAI('content', 'The content to write to the file', 'string');
const fs = require('fs');
const path = require('path');
const os = require('os');
const HOME = os.homedir();
const resolved = path.resolve(filePath.replace(/^~/, HOME));
const homeWithSep = HOME.toLowerCase() + path.sep;
if (resolved.toLowerCase() !== HOME.toLowerCase() && !resolved.toLowerCase().startsWith(homeWithSep)) {
  return 'Error: access denied - path must be within the home directory';
}
try {
  const dir = path.dirname(resolved);
  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(resolved, content, 'utf8');
  return `File written successfully: ${resolved} (${content.length} characters)`;
} catch (err) {
  return `Error writing file: ${err.message}`;
}

const loc = (($fromAI('location', 'City or location name', 'string') || '')).trim() || 'Tauranga';
const res = await fetch(`https://wttr.in/${encodeURIComponent(loc)}?format=j1`, { headers: { 'User-Agent': 'HomeBot' } });
if (!res.ok) return `Weather lookup failed (${res.status}) for ${loc}`;
const data = await res.json();
const cur = data.current_condition && data.current_condition[0];
if (!cur) return `No current conditions available for ${loc}`;
const area = data.nearest_area && data.nearest_area[0];
const name = area ? area.areaName[0].value : loc;
return `Weather in ${name}: ${cur.temp_C}°C (feels like ${cur.FeelsLikeC}°C), ${cur.weatherDesc[0].value}, humidity ${cur.humidity}%, wind ${cur.windspeedKmph} km/h`;

const dirPath = $fromAI('path', 'Directory path to list', 'string');
const fs = require('fs');
const path = require('path');
const os = require('os');
const HOME = os.homedir();
const resolved = path.resolve(dirPath.replace(/^~/, HOME));
const homeWithSep = HOME.toLowerCase() + path.sep;
if (resolved.toLowerCase() !== HOME.toLowerCase() && !resolved.toLowerCase().startsWith(homeWithSep)) {
  return 'Error: access denied - path must be within the home directory';
}
try {
  const entries = fs.readdirSync(resolved, { withFileTypes: true });
  const result = entries.slice(0, 50).map(e => {
    const icon = e.isDirectory() ? '[DIR]' : '[FILE]';
    let size = '';
    if (!e.isDirectory()) {
      try { const s = fs.statSync(path.join(resolved, e.name)); size = ` (${(s.size / 1024).toFixed(1)} KB)`; } catch {}
    }
    return `${icon} ${e.name}${size}`;
  });
  return `Contents of ${resolved}:\n${result.join('\n')}`;
} catch (err) {
  return `Error: ${err.message}`;
}

